import { useState, type ChangeEvent } from 'react';
import { withConfiguration, FormField, FormControl, FieldValueList, Input } from '@pega/cosmos-react-core';
import '../shared/create-nonce';
import StyledPegaExtensionsPolicyReferenceWrapper from './styles';

/**
 * Displays and captures a policy reference number with a configurable prefix.
 *
 * Generated by tools/generator. The props below are emitted from the same spec
 * as config.json, so the property panel and this type cannot drift.
 *
 * Authored properties:
 * - prefix: Reference prefix
 * - casing: Casing
 * - showPrefixHint: Show prefix hint
 */
type PegaExtensionsPolicyReferenceProps = {
  /** field label */
  label: string;
  /** value supplied by the platform */
  value: string;
  /** validation message */
  validatemessage?: string;
  /** placeholder text */
  placeholder?: string;
  /** helper text */
  helperText?: string;
  /** hide the label */
  hideLabel?: boolean;
  /** is the field disabled */
  disabled?: boolean;
  /** is the field read-only */
  readOnly?: boolean;
  /** is the field required */
  required?: boolean;
  /** test id */
  testId?: string;
  /** display mode */
  displayMode?: 'DISPLAY_ONLY' | 'LABELS_LEFT' | '';
  /** PConnect accessor */
  getPConnect: any;
  /** Reference prefix */
  prefix?: string;
  /** Casing */
  casing?: 'upper' | 'preserve';
  /** Show prefix hint */
  showPrefixHint?: boolean;
};

export const PegaExtensionsPolicyReference = (props: PegaExtensionsPolicyReferenceProps) => {
  const {
    label,
    value,
    placeholder,
    helperText,
    validatemessage,
    hideLabel = false,
    disabled = false,
    readOnly = false,
    required = false,
    testId,
    displayMode,
    getPConnect,
  } = props;

  const pConn = getPConnect();
  const actions = pConn.getActionsApi();
  const propName: string = pConn.getStateProps().value;

  /* TODO: wire up the authored properties. They are accepted and typed,
     but nothing reads them yet, so the property panel currently offers
     controls this component ignores. Destructure them from `props` as you
     implement each one:
       prefix = 'POL-'  // Reference prefix
       casing = 'upper'  // Casing
       showPrefixHint = true  // Show prefix hint */

  const [status, setStatus] = useState<'error' | undefined>(undefined);

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    actions.updateFieldValue(propName, event.target.value);
  };

  const handleBlur = () => {
    actions.triggerFieldChange(propName, value);
    setStatus(validatemessage ? 'error' : undefined);
  };

  if (displayMode === 'DISPLAY_ONLY') {
    return (
      <StyledPegaExtensionsPolicyReferenceWrapper>{String(value ?? '')}</StyledPegaExtensionsPolicyReferenceWrapper>
    );
  }

  if (displayMode === 'LABELS_LEFT') {
    return (
      <StyledPegaExtensionsPolicyReferenceWrapper>
        <FieldValueList
          variant={hideLabel ? 'stacked' : 'inline'}
          data-testid={testId}
          fields={[{ id: '1', name: hideLabel ? '' : label, value: String(value ?? '') }]}
        />
      </StyledPegaExtensionsPolicyReferenceWrapper>
    );
  }

  return (
    <StyledPegaExtensionsPolicyReferenceWrapper>
      <FormField
        label={label}
        labelHidden={hideLabel}
        info={validatemessage || helperText}
        status={status}
        testId={testId}
        disabled={disabled}
        readOnly={readOnly}
        required={required}
      >
        <FormControl>
          <Input
            type='text'
            value={value ?? ''}
            placeholder={placeholder}
            disabled={disabled}
            readOnly={readOnly}
            required={required}
            onChange={handleChange}
            onBlur={handleBlur}
            testId={testId}
          />
        </FormControl>
      </FormField>
    </StyledPegaExtensionsPolicyReferenceWrapper>
  );
};

export default withConfiguration(PegaExtensionsPolicyReference);
